mapper.update:
UPDATE sr_dag_instance
SET status = 18,
    last_progress_time = #{now},
    updated_at = #{now}
WHERE id = #{dagInstanceId}
  AND status = 10

UPDATE sr_dag_instance
SET heartbeat_time = #{now},
    lease_expire_time = #{leaseExpireTime},
    last_progress_time = #{now},
    updated_at = #{now}
WHERE id = #{dagInstanceId}
  AND worker_id = #{workerId}
  AND lease_version = #{leaseVersion}

UPDATE sr_dag_instance
SET finished_node_count = finished_node_count + #{delta},
    last_progress_time = #{now},
    updated_at = #{now}
WHERE id = #{dagInstanceId}
